// Squeek genes: starting stats from a Squeek's onchain traits (DotGrid `traitWord`) and level.
// DelveRules.sol applies the same tables (generated by tools/gen-tables.mjs) in `start`, so a
// ranked run's starting stats are computed onchain. tools/parity.mjs checks both sides agree.

export const STAT_KEYS = ["maxHp", "atk", "def", "crit", "dodge", "luck", "goldPct", "leech", "regen", "vision", "pebbles"];
const S = Object.fromEntries(STAT_KEYS.map((k, i) => [k, i]));
export const STAT_LABEL = {
  maxHp: "HP", atk: "ATK", def: "DEF", crit: "CRIT %", dodge: "DODGE %", luck: "LUCK", goldPct: "SEEDS %",
  leech: "LEECH", regen: "REST", vision: "SIGHT", pebbles: "PEBBLES",
};

// traitWord layout: byte 2 = palette, 3 = color pattern, 4..8 = body/face/eye/muzzle/ear glyph,
// 9 = illumination, 10 = eyes, 11 = ears, 12 = background.
export const GLYPHS = [
  ["Circle", S.maxHp, 2], ["Rounded Square", S.dodge, 2], ["Triangle", S.atk, 1], ["Diamond", S.crit, 3],
  ["Cross", S.regen, 1], ["Sparkle", S.vision, 1], ["Shield", S.def, 1], ["Capsule", S.pebbles, 2],
  ["Crown", S.goldPct, 8], ["Heart", S.maxHp, 3], ["Teardrop", S.leech, 1], ["Lightning Bolt", S.dodge, 3],
  ["Clover", S.luck, 1],
];
// Palette -> element; spectral palettes double their element's bonus.
export const ELEMENTS = [
  ["Void", S.vision, 1], ["Cyan", S.crit, 4], ["Lime", S.regen, 1], ["Orange", S.atk, 1], ["Magenta", S.leech, 1],
  ["Red", S.atk, 1], ["Ice", S.def, 1], ["RGB", S.luck, 1], ["Gold", S.goldPct, 15],
];
export const PALETTES = [
  ["Void Violet", 0, 0], ["Electric Cyan", 1, 0], ["Acid Lime", 2, 0], ["Orange CRT", 3, 0], ["Hot Magenta", 4, 0],
  ["Reactor Red", 5, 0], ["Ice White", 6, 0], ["Spectral RGB", 7, 1], ["Gold", 8, 0], ["RGB", 7, 0],
  ["Spectral Void Violet", 0, 1], ["Spectral Electric Cyan", 1, 1], ["Spectral Acid Lime", 2, 1],
  ["Spectral Orange CRT", 3, 1], ["Spectral Hot Magenta", 4, 1], ["Spectral Reactor Red", 5, 1],
  ["Spectral Ice White", 6, 1], ["Spectral Gold", 8, 1],
];
export const PATTERNS = [
  ["Solid", S.maxHp, 3], ["Vertical Split", S.crit, 2], ["Horizontal Split", S.dodge, 2],
  ["Radial Core", S.regen, 1], ["Checker", S.def, 1], ["Spectral Noise", S.luck, 1],
];
export const ILLUMINATIONS = [
  ["Balanced Field", S.maxHp, 2], ["Core Pulse", S.regen, 1], ["Rim Trace", S.vision, 1],
  ["Phase Sweep", S.dodge, 3], ["Overdrive", S.atk, 1],
];
export const EYES = [
  ["Standard Capsules", S.crit, 1], ["Wide Blocks", S.vision, 1], ["Tiny Pixels", S.crit, 2], ["Sleepy Bars", S.regen, 1],
  ["X Expression", S.atk, 1], ["Reticle", S.crit, 4], ["Vertical Slits", S.dodge, 2], ["Focused Chevrons", S.crit, 3],
  ["Happy Arcs", S.luck, 1], ["Broken Signal", S.dodge, 3], ["Wink", S.luck, 1], ["Orbit Rings", S.vision, 1],
];
export const EARS = [
  ["Canonical Round", S.maxHp, 2], ["Compact Round", S.dodge, 2], ["Wide Round", S.vision, 1],
  ["Soft Square", S.def, 1], ["Notched", S.atk, 1], ["Hollow Ring", S.pebbles, 3],
];
export const BACKGROUNDS = [
  ["Dot Grid", S.pebbles, 2], ["Micro Dots", S.luck, 1], ["Wide Dots", S.goldPct, 5],
  ["Scanlines", S.crit, 2], ["Cross Grid", S.def, 1],
];
export const HANDS = ["No match", "Pair", "Two pair", "Three of a kind", "Full house", "Four of a kind", "Five of a kind"];
export const RARITIES = ["Common", "Uncommon", "Rare", "Epic", "Legendary"];
export const RARITY_COLORS = ["#c9c2b2", "#7fd67a", "#6fb4ff", "#c58cff", "#ffb53d"];
const HAND_TIER = [0, 1, 2, 3, 4, 4, 4];
const SPECTRAL_GOLD = 17;

const byte = (word, i) => Number((BigInt(word) >> BigInt(8 * i)) & 0xffn);
const pick = (table, i) => (i < table.length ? table[i] : null);

/** Decodes a traitWord into stat bonuses. Returns null for a missing word. */
export function genes(word) {
  if (word === null || word === undefined || BigInt(word) === 0n) return null;
  const bonus = new Array(STAT_KEYS.length).fill(0);
  const add = (row, mult = 1) => { if (row) bonus[row[1]] += row[2] * mult; };
  const parts = [];

  const pal = byte(word, 2);
  const palRow = pick(PALETTES, pal);
  if (palRow) add(ELEMENTS[palRow[1]], palRow[2] ? 2 : 1);
  add(pick(PATTERNS, byte(word, 3)));

  // Glyph hand: matching glyphs across the 5 glyph slots multiply that glyph's bonus.
  const counts = new Map();
  for (let b = 4; b <= 8; b++) { const gph = byte(word, b); counts.set(gph, (counts.get(gph) ?? 0) + 1); }
  const sizes = [];
  for (const [gph, k] of counts) {
    add(pick(GLYPHS, gph), (k * (k + 1)) / 2);
    sizes.push(k);
  }
  sizes.sort((a, b) => b - a);
  const hand = sizes[0] === 5 ? 6 : sizes[0] === 4 ? 5 : sizes[0] === 3 && sizes[1] === 2 ? 4
    : sizes[0] === 3 ? 3 : sizes[0] === 2 && sizes[1] === 2 ? 2 : sizes[0] === 2 ? 1 : 0;

  add(pick(ILLUMINATIONS, byte(word, 9)));
  add(pick(EYES, byte(word, 10)));
  add(pick(EARS, byte(word, 11)));
  add(pick(BACKGROUNDS, byte(word, 12)));

  const tier = Math.min(4, HAND_TIER[hand] + (pal === SPECTRAL_GOLD ? 1 : 0));
  bonus[S.maxHp] += 3 * tier;
  bonus[S.atk] += Math.floor(tier / 2);
  bonus[S.crit] += 2 * tier;
  bonus[S.goldPct] += 5 * tier;
  for (let b = 4; b <= 8; b++) parts.push(GLYPHS[byte(word, b)]?.[0] ?? "?");
  return { tier, hand, bonus, glyphs: parts, palette: palRow?.[0] ?? "?" };
}

/** Bonus object keyed by stat name, for display. */
export const bonusMap = (g) => (g ? Object.fromEntries(STAT_KEYS.map((k, i) => [k, g.bonus[i]])) : null);
